// Takes a part of Tarjei Krogh's STAB LAB into Dropfather: the synth chord sounds (not the legacy ones) and the
// chord-line rhythms, with their STAB LAB names, generated by STAB LAB's own code. The editor, the six-oscillator
// sound designer, the tone recipes, the delay banks and the recorder stay in STAB LAB.
// Usage: node tools/extract-stablab.mjs STAB-LAB-v0.4.html  → src/vendor/stablab-data.js
import fs from 'node:fs';
import path from 'node:path';

const src = fs.readFileSync(process.argv[2], 'utf8');
function block(from) {
  let depth = 0, quote = null;
  for (let i = from; i < src.length; i++) {
    const c = src[i];
    if (quote) { if (c === '\\') i++; else if (c === quote) quote = null; continue; }
    if (c === '"' || c === "'" || c === '`') quote = c;
    else if (c === '{' || c === '[' || c === '(') depth++;
    else if (c === '}' || c === ']' || c === ')') { depth--; if (!depth) return src.slice(from, i + 1); }
  }
  throw Error('unclosed block at ' + from);
}
const literal = name => { const at = src.indexOf(`const ${name}=`); if (at < 0) throw Error(name + ' not found'); const open = src.slice(at).search(/[\[{]/) + at; return block(open); };
const parts = ['NB_CHORD_PRESETS', 'NB_SYN_POLY', 'clSounds', 'clLines', 'clProgressions', 'ST_NAMES'].map(n => `const ${n}=${literal(n)};`).join('\n');
// STAB LAB's generator: from the old banks to the 333-sound and 333-line libraries.
const a = src.indexOf('const oldSounds=clSounds'), b = src.indexOf('const drumLibrary=', a);
const gen = src.slice(a, b);
const run = Function('clamp', `${parts}\n${gen}\nfor(let i=0;i<333;i++){soundLibrary[i].name=ST_NAMES.sounds[i];lineLibrary[i].name=ST_NAMES.lines[i];}\nreturn {soundLibrary,lineLibrary};`);
const { soundLibrary, lineLibrary } = run((x, lo, hi) => Math.max(lo, Math.min(hi, x)));

const sounds = soundLibrary.map((s, i) => ({ i, name: s.name, engine: s.engine, patch: s.patch })).filter(s => s.engine !== 'legacy');
const lines = lineLibrary.map((l, i) => ({ i, name: l.name, hits: l.hits, period: l.period }));
const out = path.join(path.dirname(new URL(import.meta.url).pathname), '..', 'src', 'vendor', 'stablab-data.js');
fs.writeFileSync(out, `/* From STAB LAB v0.4 by Tarjei Krogh: its synth chord sounds and chord lines, as generated by STAB LAB itself. Generated by tools/extract-stablab.mjs. */\nwindow.STABLAB_DATA=${JSON.stringify({ sounds, lines })};\n`);
console.log(sounds.length, 'sounds (', [...new Set(sounds.map(s => s.engine))].join(', '), '),', lines.length, 'lines →', out, fs.statSync(out).size, 'bytes');
